query ($facility: String!, $co: String!, $style: String!, $warehouses: [String!]!, $company: Float!) {
  getAllScheduleNumbersAddRelease(
    style: $style
    co: $co
    facility: $facility
    warehouses: $warehouses
    company: $company
  ) {
    mainProduct
    referenceOrderNumber
    scheduleNumber
    __typename
  }
}
